mapper.select:
SELECT u.id, u.username, u.name, u.phone, COUNT(t.id) AS activeTicketCount, u.enabled FROM sys_user u JOIN sys_user_role ur ON ur.user_id = u.id JOIN sys_role r ON r.id = ur.role_id LEFT JOIN ticket t ON t.assignee_id = u.id AND t.status NOT IN ('COMPLETED', 'CANCELLED', 'CLOSED') WHERE r.role_code = 'REPAIRER'
AND u.enabled = #{enabled}
AND ( NULLIF(TRIM(#{keyword}), '') IS NULL OR u.username LIKE CONCAT('%', TRIM(#{keyword}), '%') OR u.name LIKE CONCAT('%', TRIM(#{keyword}), '%') ) GROUP BY u.id, u.username, u.name, u.phone, u.enabled ORDER BY u.id
